{
  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "न कश्चिच्चण्डकोपानामात्मीयो नाम भूभुजाम् ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "होतारमपि जुव्हानं स्पृष्टो दहति पावकः ॥ ५७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "मौनान्मूकः प्रवचनपटुश्चाटुलो जल्पको वा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "",
          "end": "line"
        },
        {
          "n": 3,
          "text": "धृष्टः पार्श्वे वसति च तदा दूरतश्चाप्रगल्भः ।",
          "end": "line"
        },
        {
          "n": 4,
          "text": "क्षान्त्या भीरुर्यदि न सहते प्रायशो नाभिजातः",
          "end": "line"
        },
        {
          "n": 5,
          "text": "सेवाधर्मः परमगहनो योगिनामप्यगम्यः ॥ ५८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "उद्भासिताखिलखलस्य विशृङ्खलस्य",
          "end": "line"
        },
        {
          "n": 2,
          "text": "प्राग्जातविस्तृतनिजाधमकर्मवृत्तेः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "line"
        },
        {
          "n": 4,
          "text": "दैवादवाप्तविभवस्य गुणद्विषोस्य",
          "end": "line"
        },
        {
          "n": 5,
          "text": "नीचस्य गोचरगतैः सुखमास्यते कैः ॥ ५९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "आरम्भगुर्वी क्षयिणी क्रमेण",
          "end": "line"
        },
        {
          "n": 2,
          "text": "लघ्वी पुरा वृद्धिमती च पश्चात् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "line"
        },
        {
          "n": 4,
          "text": "दिनस्य पूर्वार्धपरार्धभिन्ना",
          "end": "line"
        },
        {
          "n": 5,
          "text": "",
          "end": "line"
        },
        {
          "n": 6,
          "text": "छायेव मैत्री खलसज्जनानाम् ॥ ६० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "apparatus_entry",
      "lines": [
        {
